// Package report renders recorded findings into a client-ready penetration
// test report (Markdown and self-contained HTML).
//
// Everything here is deterministic: counts, ordering, the executive summary and
// the overall rating are derived from the findings, never generated by a model,
// so the report cannot contradict its own data.
//
// Finding text is untrusted. Evidence in particular quotes responses from the
// systems under test, which may contain markup or script. The HTML output is
// escaped by html/template and the Markdown output neutralizes raw HTML and
// code-fence breakouts.
package report

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Severity values, in report order from most to least severe.
var severityOrder = []string{"critical", "high", "medium", "low", "info"}

var severityLabel = map[string]string{
	"critical": "Critical",
	"high":     "High",
	"medium":   "Medium",
	"low":      "Low",
	"info":     "Informational",
}

// Finding is the report's view of a recorded finding.
type Finding struct {
	ID          int64
	Title       string
	Asset       string
	Severity    string // critical|high|medium|low|info
	Status      string // confirmed|potential|false_positive
	CVSSVector  string
	CVSSScore   float64
	Description string
	Impact      string
	Evidence    string
	Remediation string
	References  []string
	Reviewed    bool // a person has reviewed or edited this finding
}

// Meta describes the engagement the report covers.
type Meta struct {
	Title       string    // engagement / flow title
	Company     string    // the consultancy issuing the report
	Client      string    // optional client name
	Scope       []string  // authorized targets
	TestStart   time.Time // zero if unknown
	TestEnd     time.Time // zero if unknown
	GeneratedAt time.Time
}

// Entry is a finding as it appears in the report, with its report number.
type Entry struct {
	Finding
	Number string // F-01, F-02, ...
	Label  string // human severity label
}

// Document is a report ready to render.
type Document struct {
	Meta
	Findings  []Entry
	Counts    map[string]int // by severity, over included findings
	Confirmed int
	Potential int
	Reviewed  int
	// Draft is true while any included finding has not been reviewed by a person.
	Draft bool
	// Overall is the highest severity present, as a label.
	Overall string
}

// Build prepares a document: it drops false positives, normalizes severities,
// orders findings by severity then CVSS score, and numbers them.
func Build(meta Meta, in []Finding) Document {
	doc := Document{Meta: meta, Counts: map[string]int{}}

	included := make([]Finding, 0, len(in))
	for _, f := range in {
		f.Severity = strings.ToLower(strings.TrimSpace(f.Severity))
		if _, ok := severityLabel[f.Severity]; !ok {
			f.Severity = "info"
		}
		f.Status = strings.ToLower(strings.TrimSpace(f.Status))
		if f.Status == "false_positive" {
			continue
		}
		if f.Status != "confirmed" {
			f.Status = "potential"
		}
		included = append(included, f)
	}

	rank := make(map[string]int, len(severityOrder))
	for i, s := range severityOrder {
		rank[s] = i
	}
	sort.SliceStable(included, func(i, j int) bool {
		a, b := included[i], included[j]
		if rank[a.Severity] != rank[b.Severity] {
			return rank[a.Severity] < rank[b.Severity]
		}
		if a.CVSSScore != b.CVSSScore {
			return a.CVSSScore > b.CVSSScore
		}
		return a.ID < b.ID
	})

	for i, f := range included {
		doc.Findings = append(doc.Findings, Entry{
			Finding: f,
			Number:  fmt.Sprintf("F-%02d", i+1),
			Label:   severityLabel[f.Severity],
		})
		doc.Counts[f.Severity]++
		if f.Status == "confirmed" {
			doc.Confirmed++
		} else {
			doc.Potential++
		}
		if f.Reviewed {
			doc.Reviewed++
		} else {
			doc.Draft = true
		}
	}

	doc.Overall = "None"
	for _, s := range severityOrder {
		if doc.Counts[s] > 0 {
			doc.Overall = severityLabel[s]
			break
		}
	}

	return doc
}

// Summary returns the executive-summary paragraph(s), derived from the data.
func (d Document) Summary() string {
	total := len(d.Findings)
	if total == 0 {
		return "No security findings were recorded during this assessment."
	}

	var parts []string
	for _, s := range severityOrder {
		if n := d.Counts[s]; n > 0 {
			parts = append(parts, fmt.Sprintf("%d %s", n, strings.ToLower(severityLabel[s])))
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "This assessment identified %d %s: %s. The overall risk rating is %s, set by the most severe finding. ",
		total, plural(total, "finding", "findings"), strings.Join(parts, ", "), d.Overall)
	fmt.Fprintf(&b, "%d %s confirmed with evidence", d.Confirmed, plural(d.Confirmed, "was", "were"))
	if d.Potential > 0 {
		fmt.Fprintf(&b, "; %d %s indicated but could not be verified and should be validated", d.Potential, plural(d.Potential, "issue is", "issues are"))
	}
	b.WriteString(".")

	top := d.topTitles(3)
	if len(top) > 0 {
		b.WriteString(" The most significant: " + strings.Join(top, "; ") + ".")
	}
	return b.String()
}

func (d Document) topTitles(n int) []string {
	var out []string
	for _, e := range d.Findings {
		if e.Severity == "info" {
			break // informational items are never "most significant"
		}
		out = append(out, fmt.Sprintf("%s (%s, %s)", oneLine(e.Title), e.Number, strings.ToLower(e.Label)))
		if len(out) == n {
			break
		}
	}
	return out
}

// ReviewNotice states the review status honestly: the report only claims human
// review once every included finding has been reviewed.
func (d Document) ReviewNotice() string {
	switch {
	case len(d.Findings) == 0:
		return ""
	case d.Draft:
		return fmt.Sprintf("DRAFT: %d of %d findings have been reviewed by a consultant. "+
			"Findings recorded by the automated testing platform must be reviewed before this report is issued.",
			d.Reviewed, len(d.Findings))
	default:
		return "All findings in this report were reviewed by a consultant."
	}
}

// Methodology is the fixed description of how testing was performed.
const Methodology = "Testing was performed with an AI-assisted penetration testing platform, working within the scope above. " +
	"The platform carried out reconnaissance, vulnerability analysis and, where authorized, controlled exploitation, " +
	"recording each issue with its supporting evidence. Severity follows the CVSS v3.1 base score where a vector is given."

// Disclaimer is the fixed point-in-time disclaimer.
const Disclaimer = "This report reflects the state of the in-scope systems at the time of testing. " +
	"Absence of a finding does not prove absence of a vulnerability. New vulnerabilities may appear as systems change."

func plural(n int, one, many string) string {
	if n == 1 {
		return one
	}
	return many
}

// oneLine collapses all whitespace (including newlines) so a value can sit on
// a single line such as a heading or a table cell.
func oneLine(s string) string {
	return strings.Join(strings.Fields(s), " ")
}
